<script setup lang="ts">
import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import * as echarts from 'echarts/core'
import { BarChart } from 'echarts/charts'
import { GridComponent, TooltipComponent } from 'echarts/components'
import { CanvasRenderer } from 'echarts/renderers'
import type { ECharts } from 'echarts/core'
import { api, ApiError } from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'

echarts.use([BarChart, GridComponent, TooltipComponent, CanvasRenderer])
type Overview={pending_reviews:number;open_items:number;active_claims:number;completed_returns:number;failed_tasks:number|null;item_review_statuses:{review_status:string;count:number}[];claim_statuses:{status:string;count:number}[];stations:number;scope:string}
const data=ref<Overview|null>(null);const error=ref('');const loading=ref(true);const chartHost=ref<HTMLDivElement|null>(null);let chart:ECharts|null=null
const modules=[
  {to:'/admin/reviews',label:'待审核队列',icon:'shield' as const},{to:'/admin/claims',label:'认领与交接',icon:'user' as const},
  {to:'/admin/matching/config',label:'匹配参数',icon:'spark' as const},{to:'/admin/system',label:'系统与审计',icon:'box' as const},
]
function resize(){chart?.resize()}
function draw(){if(!chartHost.value||!data.value)return;chart?.dispose();chart=echarts.init(chartHost.value,undefined,{renderer:'canvas'});chart.setOption({backgroundColor:'transparent',tooltip:{trigger:'axis'},grid:{left:45,right:18,top:25,bottom:55},xAxis:{type:'category',data:data.value.item_review_statuses.map(entry=>entry.review_status),axisLabel:{color:'#a9b8ca',rotate:18},axisLine:{lineStyle:{color:'#38506b'}}},yAxis:{type:'value',axisLabel:{color:'#a9b8ca'},splitLine:{lineStyle:{color:'rgba(171,199,229,.08)'}}},series:[{name:'物品数',type:'bar',data:data.value.item_review_statuses.map(entry=>entry.count),itemStyle:{color:'#f5b942',borderRadius:[5,5,0,0]}}]})}
onMounted(async()=>{try{const response=await api<{data:Overview}>('/admin/overview/');data.value=response.data;loading.value=false;await nextTick();draw();window.addEventListener('resize',resize)}catch(reason){error.value=reason instanceof ApiError?reason.message:'无法读取运营指标';loading.value=false}})
onBeforeUnmount(()=>{window.removeEventListener('resize',resize);chart?.dispose();chart=null})
</script>
<template><div class="page admin-page"><header><div><p class="eyebrow">B01 · OPERATIONS OVERVIEW</p><h1 class="page-title">运营总览</h1><p class="page-lead">指标来自当前登录角色的后端权限范围；协调员只看已授权站点，管理员查看全局。</p></div><span v-if="data" class="scope">{{data.scope}}</span></header><p v-if="loading" class="state">正在读取真实运营数据…</p><p v-else-if="error" class="state error">{{error}}</p><template v-else-if="data"><section class="kpis"><article><span>待审核</span><strong>{{data.pending_reviews}}</strong><small>内容待办</small></article><article><span>开放线索</span><strong>{{data.open_items}}</strong><small>已审核且可用</small></article><article><span>活跃认领</span><strong>{{data.active_claims}}</strong><small>未结束流程</small></article><article><span>已完成归还</span><strong>{{data.completed_returns}}</strong><small>双方确认记录</small></article></section><section class="module-grid"><RouterLink v-for="module in modules" :key="module.to" :to="module.to" class="module-card"><AppIcon :name="module.icon"/><div><span>管理模块</span><strong>{{module.label}}</strong></div><AppIcon name="arrow"/></RouterLink></section><div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-head"><div><p class="eyebrow">LIVE DATABASE COUNTS</p><h2>物品审核状态</h2></div><span class="status-tag">{{data.stations}} 个服务站</span></div><div ref="chartHost" class="chart" role="img" aria-label="真实物品审核状态柱状图"></div></section><aside class="panel gate-panel"><p class="eyebrow">ACCEPTANCE GATES</p><h2>当前门禁诚实状态</h2><ul><li><span class="dot pass"></span><div><strong>G02 MySQL 8.4</strong><small>PASS · 360 条固定演示数据</small></div></li><li><span class="dot pass"></span><div><strong>G05 匹配算法</strong><small>PASS · 单测与 B0–B3/消融已运行</small></div></li><li><span class="dot pass"></span><div><strong>G07 页面系统</strong><small>PASS · 40 个业务页与 8 个系统页已遍历</small></div></li></ul><p v-if="data.failed_tasks!==null" class="failed"><strong>{{data.failed_tasks}}</strong>个失败持久任务待处理</p></aside></div></template></div></template>
<style scoped>.admin-page>header{display:flex;justify-content:space-between;align-items:end;gap:20px}.scope{padding:10px 14px;color:var(--ct-info);border:1px solid var(--ct-border);border-radius:10px}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:34px 0 15px}.kpis article{padding:20px;border:1px solid var(--ct-border);border-radius:14px;background:var(--ct-surface)}.kpis span,.kpis small{display:block;color:var(--ct-text-muted);font-size:11px}.kpis strong{display:block;margin:8px 0;color:var(--ct-brand);font-size:32px}.module-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}.module-card{display:grid;grid-template-columns:auto 1fr auto;gap:13px;align-items:center;padding:17px;border:1px solid var(--ct-border);border-radius:14px;background:var(--ct-surface)}.module-card>svg:first-child{color:var(--ct-brand);font-size:24px}.module-card span,.module-card small{display:block;color:var(--ct-text-muted);font-size:10px}.module-card strong{display:block;margin-top:3px}.dashboard-grid{display:grid;grid-template-columns:1fr 360px;gap:18px}.chart-panel,.gate-panel{padding:24px;box-shadow:none}.panel-head{display:flex;justify-content:space-between;align-items:start}.panel-head h2{margin:10px 0 0}.chart{height:360px}.gate-panel h2{margin:14px 0 24px}.gate-panel ul{display:grid;gap:22px;margin:0;padding:0;list-style:none}.gate-panel li{display:flex;gap:12px}.gate-panel small{display:block;margin-top:5px;color:var(--ct-text-muted)}.dot{width:10px;height:10px;margin-top:5px;border-radius:50%}.dot.pass{background:var(--ct-success);box-shadow:0 0 12px var(--ct-success)}.dot.not-run{background:var(--ct-brand);box-shadow:0 0 12px var(--ct-brand)}.failed{margin-top:28px;padding:13px;color:var(--ct-text-muted);border:1px dashed var(--ct-border);border-radius:10px}.failed strong{color:var(--ct-danger);font-size:22px}.state{display:grid;place-items:center;min-height:400px}.error{color:var(--ct-danger)}@media(max-width:900px){.kpis,.module-grid{grid-template-columns:1fr 1fr}.dashboard-grid{grid-template-columns:1fr}}@media(max-width:560px){.kpis,.module-grid{grid-template-columns:1fr}.admin-page>header{align-items:start;flex-direction:column}}</style>
